// 多人可选同一个策略 (业主 2026-10-24): data/config.json bandDraft.duplicatesAllowed (generated by
// tools/build-data.mjs, read through shared/bandDraft.js) is TRUE, and with it two seats of one co-op match may take the
// same strategy. The client's draft helpers therefore stop hunting for a free band: a turn that runs out gives the
// timeout default (bandDraft.timeoutBandId, 「华法琳」) outright, a teammate's pick never blocks 确认选择 and the card
// keeps only the 「谁选了这张」 avatars (screens/bandDraft.js). The switch is backwards compatible — a call site that
// passes no options gets duplicates allowed, i.e. the official rule — and turning it off (duplicatesAllowed: false, a
// config / mode override) restores the old 「队友已选」 behaviour word for word (test/ui/bandDraft.test.js pins that
// half against the live server). This file pins both directions of the pure helpers.

import { test, describe } from 'node:test';
import assert from 'node:assert/strict';

import { BAND_DRAFT_DEFAULTS, bandDuplicatesAllowed } from '../../shared/bandDraft.js';
import {
  allowedBands, autoPickBand, draftSelection, duplicatesAllowedOf, teammateBands, timeoutBand,
} from '../../public/js/screens/bandDraft.js';

const bands = allowedBands([
  { bandId: 'band_bldsk', sortId: 1 }, { bandId: 'band_amiya', sortId: 2 }, { bandId: 'band_duyaoy', sortId: 3 },
], 'MULTI');
const BANDS = bands.map((b) => b.bandId); // ['band_bldsk', 'band_amiya', 'band_duyaoy']

describe('the switch itself: allowed unless the data says otherwise', () => {
  test('shared/bandDraft.js: the built-in default is allow, and a missing / malformed config means the same', () => {
    assert.equal(BAND_DRAFT_DEFAULTS.duplicatesAllowed, true);
    assert.equal(bandDuplicatesAllowed(undefined), true);
    assert.equal(bandDuplicatesAllowed(null), true);
    assert.equal(bandDuplicatesAllowed({}), true, 'no bandDraft block');
    assert.equal(bandDuplicatesAllowed({ bandDraft: {} }), true, 'no key');
    assert.equal(bandDuplicatesAllowed({ bandDraft: { duplicatesAllowed: 'no' } }), true, 'not a boolean');
    assert.equal(bandDuplicatesAllowed({ bandDraft: { duplicatesAllowed: 0 } }), true, 'not a boolean');
    assert.equal(bandDuplicatesAllowed({ bandDraft: { duplicatesAllowed: false } }), false, 'off stays off');
    assert.equal(bandDuplicatesAllowed({ bandDraft: { duplicatesAllowed: true } }), true);
  });

  test('duplicatesAllowedOf: the published m.public.draft verdict wins, then data/config.json, then the default', () => {
    assert.equal(duplicatesAllowedOf({ draft: { duplicatesAllowed: false } }, { bandDraft: { duplicatesAllowed: true } }), false, 'the server decides');
    assert.equal(duplicatesAllowedOf({ draft: { duplicatesAllowed: true } }, { bandDraft: { duplicatesAllowed: false } }), true);
    assert.equal(duplicatesAllowedOf({ draft: {} }, { bandDraft: { duplicatesAllowed: false } }), false, 'no published field: the config');
    assert.equal(duplicatesAllowedOf({ draft: { duplicatesAllowed: 'yes' } }, { bandDraft: { duplicatesAllowed: false } }), false, 'a non-boolean is no verdict');
    assert.equal(duplicatesAllowedOf(null, null), true, 'nothing at all: the official rule');
    assert.equal(duplicatesAllowedOf(undefined, {}), true);
    assert.equal(duplicatesAllowedOf({}, { bandDraft: { duplicatesAllowed: 'off' } }), true);
  });
});

describe('duplicates allowed (the default): a timeout gives the default strategy, never a free-band hunt', () => {
  test('timeoutBand: the timeout default whatever a teammate holds', () => {
    const free = new Map();
    const amiTaken = new Map([['band_amiya', ['p2']]]);
    const bldskTaken = new Map([['band_bldsk', ['p2']]]);
    const allTaken = new Map(BANDS.map((id) => [id, ['p2']]));
    for (const o of [undefined, {}, { duplicatesAllowed: true }]) {
      assert.equal(timeoutBand(bands, free, undefined, o), 'band_bldsk', 'nothing taken');
      assert.equal(timeoutBand(bands, amiTaken, undefined, o), 'band_bldsk');
      assert.equal(timeoutBand(bands, bldskTaken, undefined, o), 'band_bldsk', 'a teammate holding 华法琳 changes nothing');
      assert.equal(timeoutBand(bands, allTaken, undefined, o), 'band_bldsk', 'even every strategy held');
      assert.equal(timeoutBand([], new Map(), undefined, o), 'band_bldsk', 'no data yet: the official default');
      assert.equal(timeoutBand(bands, null, undefined, o), 'band_bldsk', 'no taken map at all');
    }
    assert.equal(timeoutBand(bands, bldskTaken, 'band_amiya'), 'band_amiya', 'an overridden default is still the default');
  });

  test('autoPickBand: the highlighted strategy even when a teammate holds it; else the default', () => {
    const taken = new Map([['band_duyaoy', ['p2']], ['band_bldsk', ['p3']]]);
    for (const o of [undefined, {}, { duplicatesAllowed: true }]) {
      assert.equal(autoPickBand('band_duyaoy', { bands, taken, ...o }), 'band_duyaoy', 'the highlight is not blocked');
      assert.equal(autoPickBand('band_bldsk', { bands, taken, myPick: null, ...o }), 'band_bldsk');
      assert.equal(autoPickBand(null, { bands, taken, ...o }), 'band_bldsk', 'no highlight: the default (held or not)');
      assert.equal(autoPickBand('band_unknown', { bands, taken, ...o }), 'band_bldsk', 'not a strategy of the mode: the default');
      assert.equal(autoPickBand('band_amiya', { bands, taken, myPick: 'band_amiya', ...o }), null, 'nothing after my pick');
    }
  });

  test('draftSelection: nothing is moved off a strategy a teammate holds, and the default is the timeout default', () => {
    const taken = new Map([['band_bldsk', ['p2']]]);
    for (const o of [undefined, {}, { duplicatesAllowed: true }]) {
      assert.equal(draftSelection(null, { bands, taken, myPick: null, myTurn: false, ...o }), 'band_bldsk', 'the default even while held');
      assert.equal(draftSelection('band_bldsk', { bands, taken, myPick: null, myTurn: true, ...o }), 'band_bldsk', 'my turn on a held band: it stays');
      assert.equal(draftSelection('band_duyaoy', { bands, taken, myPick: null, myTurn: true, ...o }), 'band_duyaoy', 'a free pick stays');
      assert.equal(draftSelection(null, { bands, taken, myPick: 'band_amiya', myTurn: false, ...o }), 'band_amiya', 'my pick wins');
      assert.equal(draftSelection('x', { bands: [], taken, myPick: null, myTurn: true, ...o }), 'x', 'no bands: unchanged');
    }
  });

  test('the old call sites are untouched: four / three / two arguments, no options ⇒ duplicates allowed', () => {
    const taken = new Map([['band_bldsk', ['p2']], ['band_amiya', ['p3']]]);
    assert.equal(timeoutBand(bands, taken), 'band_bldsk', 'timeoutBand(bands, taken)');
    assert.equal(timeoutBand(bands, taken, 'band_duyaoy'), 'band_duyaoy', 'timeoutBand(bands, taken, defaultId)');
    assert.equal(autoPickBand('band_bldsk', { bands, taken, myPick: null }), 'band_bldsk');
    assert.equal(draftSelection('band_bldsk', { bands, taken, myPick: null, myTurn: true }), 'band_bldsk');
  });

  test('teammateBands is unchanged: it still feeds the 「谁选了这张」 avatars', () => {
    const picks = new Map([['p2', 'band_bldsk'], ['p3', 'band_bldsk'], ['p4', 'band_amiya'], ['me', 'band_duyaoy']]);
    const who = teammateBands(picks, 'me');
    assert.deepEqual([...who.keys()].sort(), ['band_amiya', 'band_bldsk']);
    assert.deepEqual(who.get('band_bldsk'), ['p2', 'p3'], 'two teammates on one strategy is exactly the new case');
    assert.equal(who.has('band_duyaoy'), false, 'never the viewer');
  });
});

describe('duplicates forbidden (duplicatesAllowed: false): the 队友已选 behaviour, word for word', () => {
  test('timeoutBand: 华法琳 while free, else the first free strategy, never a held one', () => {
    const o = { duplicatesAllowed: false };
    assert.equal(timeoutBand(bands, new Map(), undefined, o), 'band_bldsk');
    assert.equal(timeoutBand(bands, new Map([['band_amiya', ['a']]]), undefined, o), 'band_bldsk');
    assert.equal(timeoutBand(bands, new Map([['band_bldsk', ['a']]]), undefined, o), 'band_amiya');
    assert.equal(timeoutBand(bands, new Map([['band_bldsk', ['a']], ['band_amiya', ['b']]]), undefined, o), 'band_duyaoy');
    assert.equal(timeoutBand([], new Map(), undefined, o), 'band_bldsk', 'no data yet: the official default');
    assert.equal(timeoutBand(bands, null, undefined, o), 'band_bldsk');
  });

  test('autoPickBand: a held highlight falls back to the default; a free one is taken', () => {
    const o = { duplicatesAllowed: false };
    assert.equal(autoPickBand('band_duyaoy', { bands, taken: new Map(), ...o }), 'band_duyaoy');
    assert.equal(autoPickBand('band_duyaoy', { bands, taken: new Map([['band_duyaoy', ['a']]]), ...o }), 'band_bldsk', '队友已选 ⇒ the default');
    assert.equal(autoPickBand(null, { bands, taken: new Map(), ...o }), 'band_bldsk');
    assert.equal(autoPickBand('band_unknown', { bands, taken: new Map(), ...o }), 'band_bldsk', 'not a band of the mode');
    assert.equal(autoPickBand('band_amiya', { bands, taken: new Map([['band_bldsk', ['a']], ['band_amiya', ['b']]]), ...o }), 'band_duyaoy');
    assert.equal(autoPickBand('band_amiya', { bands, taken: new Map(), myPick: 'band_amiya', ...o }), null);
  });

  test('draftSelection: my turn moves off a band a teammate took; browsing it while waiting is fine', () => {
    const o = { duplicatesAllowed: false };
    const taken = new Map([['a', ['p1']]]);
    const three = [{ bandId: 'a' }, { bandId: 'b' }, { bandId: 'c' }];
    assert.equal(draftSelection(null, { bands: three, taken, myPick: null, myTurn: false, ...o }), 'b', 'default: first free');
    assert.equal(draftSelection(null, { bands: three, taken, myPick: 'c', myTurn: false, ...o }), 'c', 'default: my pick');
    assert.equal(draftSelection('a', { bands: three, taken, myPick: null, myTurn: false, ...o }), 'a', 'browsing a taken band while waiting');
    assert.equal(draftSelection('a', { bands: three, taken, myPick: null, myTurn: true, ...o }), 'b', 'my turn: off the taken band');
    assert.equal(draftSelection('c', { bands: three, taken, myPick: null, myTurn: true, ...o }), 'c', 'a free selection is kept');
    assert.equal(draftSelection('a', { bands: three, taken, myPick: 'c', myTurn: false, ...o }), 'a', 'after my pick nothing moves');
    assert.equal(draftSelection('x', { bands: [], taken, myPick: null, myTurn: true, ...o }), 'x', 'no bands: unchanged');
  });
});

describe('the screen reads the same switch', () => {
  test('it gates the 队友已选 marks on it and keeps the avatars in both directions', async () => {
    const { readFileSync } = await import('node:fs');
    const path = await import('node:path');
    const { fileURLToPath } = await import('node:url');
    const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
    const src = readFileSync(path.join(ROOT, 'public/js/screens/bandDraft.js'), 'utf8');
    assert.match(src, /const dupesAllowed = duplicatesAllowedOf\(pub, gd\.config\)/, 'the switch comes from the published draft, else gd.config');
    assert.match(src, /const isTakenOn = \(bandId\) => !dupesAllowed && taken\.has\(bandId\)/, 'taken only with duplicates forbidden');
    assert.match(src, /const selTaken = !!band && isTakenOn\(band\.bandId\)/, '确认选择 follows the same gate');
    assert.doesNotMatch(src, /is-taken[^\n]*dupesAllowed/, 'taken cards are never forced on');
    assert.match(src, /pickers\.get\(b\.bandId\)/, 'the avatars still say who picked a strategy');
    assert.match(src, /duplicatesAllowed: dupesAllowed/, 'the helpers get the switch');
    assert.match(src, /isTaken && 'is-taken'/, 'the greying comes from that same gated flag, never unconditionally');
  });
});
